// 编辑页直接使用公开接口，无需编译或包内客户端库。
const $ = QF.dom.$, on = QF.dom.on;
const copy = value => JSON.parse(JSON.stringify(value));
let context, question, acceptedQuestion, edits = 0, actionBusy = false, initialized = false;

await QF.page.register({
  onLoad(next) {
    context = next;
    if (!edits) question = acceptedQuestion = copy(next.question.data);
    if (initialized) refresh();
  },
  // 输入事件立即保存；SDK 等待这些写入完成后才允许切题或正式保存。
  onBeforeLeave: () => ({ok: true, data: {pendingSave: null}})
});
QF.page.configure({initialLayout: {cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'top', padding: 20}});
QF.ui.configure({title: false, save: false, position: false, typeLabel: false, add: false, duplicate: false, delete: false, sources: false});

// 标准答案属于 question；不要把用户作答存入这里，也不要改题目 id/type。
async function update(patch) {
  question = {...question, ...patch};
  const candidate = copy(question);
  edits++;
  try {
    const reply = await QF.save({purpose: 'editDraft', data: {questionData: candidate}});
    if (reply.ok) acceptedQuestion = candidate;
    else {
      if (edits === 1) question = copy(acceptedQuestion);
      QF.ui.notify(reply.error.message);
    }
    return reply;
  } finally { edits--; }
}
async function runAction(action) {
  if (actionBusy) return;
  actionBusy = true; refresh();
  try {
    const reply = await action();
    if (!reply.ok) QF.ui.notify(reply.error.message);
    return reply;
  } finally { actionBusy = false; refresh(); }
}
const action = (name, params = {}) => QF.requestAction({action: name, params});

function refresh() {
  const permissions = context.permissions, granted = context.grantedPermissions;
  const available = Boolean(permissions.manageQuestions);
  $('[data-bank-save]').hidden = $('[data-bank-actions]').hidden = $('[data-source-section]').hidden = !available;
  $('[data-bank-position]').textContent = '第 ' + (context.navigation.index + 1) + ' / ' + context.navigation.total + ' 题';
  const select = $('[data-bank-add]');
  select.replaceChildren(new Option('＋ 新增题目', ''));
  context.types.forEach(type => select.append(new Option(type.label, type.id)));
  for (const [selector, permission] of [['[data-bank-save]', 'bank.save'], ['[data-bank-add]', 'bank.add'], ['[data-bank-duplicate]', 'bank.duplicate'], ['[data-bank-delete]', 'bank.delete'], ['[data-delete-accept]', 'bank.delete'], ['[data-source-add]', 'sources.manage']])
    $(selector).disabled = actionBusy || !available || !granted.includes(permission);
  for (const input of QF.dom.root.querySelectorAll('textarea,input'))
    input.disabled = actionBusy || !permissions.editQuestion;
  $('[data-source-link]').disabled = actionBusy || !permissions.manageSources;
  const rows = $('[data-sources]'); rows.replaceChildren();
  context.sources.forEach((source, index) => {
    const row = document.createElement('div'); row.className = 'qf-type-source';
    const open = document.createElement('button'); open.type = 'button'; open.textContent = source.label;
    open.disabled = actionBusy || !permissions.viewSources || !source.navigable; open.title = source.message;
    open.dataset.sourceAction = 'open'; open.dataset.sourceIndex = index;
    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;
    const remove = document.createElement('button'); remove.type = 'button'; remove.textContent = '移除';
    remove.disabled = actionBusy || !permissions.manageSources; remove.setAttribute('aria-label', '移除来源 ' + source.label);
    remove.dataset.sourceAction = 'remove'; remove.dataset.sourceIndex = index;
    row.append(open, message, remove); rows.append(row);
  });
}

// 页面绘制确认与管理 UI，实际保存、增删、来源解析由应用执行。
on($('[data-bank-save]'), 'click', () => runAction(() => QF.save({purpose: 'edit', data: {questionData: copy(question)}})));
on($('[data-bank-add]'), 'change', () => { const type = $('[data-bank-add]').value; if (type) return runAction(() => action('addQuestion', {type})); });
on($('[data-bank-duplicate]'), 'click', () => runAction(() => action('duplicateQuestion')));
on($('[data-bank-delete]'), 'click', () => { $('[data-delete-confirm]').hidden = false; });
on($('[data-delete-cancel]'), 'click', () => { $('[data-delete-confirm]').hidden = true; });
on($('[data-delete-accept]'), 'click', () => runAction(() => action('deleteQuestion')));
async function addSource() {
  const link = $('[data-source-link]').value;
  const reply = await runAction(() => action('addSource', {link}));
  if (reply?.ok) $('[data-source-link]').value = '';
}
on($('[data-source-add]'), 'click', addSource);
on($('[data-source-link]'), 'keydown', event => { if (event.key === 'Enter') { event.preventDefault(); return addSource(); } });
on($('[data-sources]'), 'click', event => {
  const button = event.target.closest('[data-source-action]');
  if (button && !button.disabled) return runAction(() => action(button.dataset.sourceAction === 'open' ? 'openSource' : 'removeSource', {index: Number(button.dataset.sourceIndex)}));
});

$('[data-type-title]').textContent = '判断题编辑';
$('[data-prompt]').value = question.prompt.text;
on($('[data-prompt]'), 'input', () => update({prompt: {kind: 'TEXT', text: $('[data-prompt]').value}}));
$('[data-score]').value = question.scoreSpec.defaultMaxScore;
on($('[data-score]'), 'input', () => {
  const value = $('[data-score]').value, score = Number(value);
  if (!value.trim() || !Number.isFinite(score) || score <= 0) { QF.ui.notify('分值必须是大于 0 的数字'); return; }
  return update({scoreSpec: {...question.scoreSpec, defaultMaxScore: score}});
});
const answers = [$('[data-correct-true]'), $('[data-correct-false]')];
function refreshAnswer() {
  answers.forEach((input, index) => {
    input.checked = question.answerSpec.correctOptionIds.includes(question.payload.options[index].id);
    input.closest('label').classList.toggle('selected', input.checked);
  });
}
answers.forEach((input, index) => on(input, 'change', async () => {
  await update({answerSpec: {kind: 'CHOICE', correctOptionIds: [question.payload.options[index].id]}});
  refreshAnswer();
}));
refreshAnswer();
QF.content.mountEditor($('[data-analysis]'), {value: question.analysis, formatting: true, onChange: analysis => update({analysis})});
initialized = true; refresh();

assets.rendererSource:
// 练习、草稿、历史、预览共用此脚本；写入能力由宿主上下文决定。
const $ = QF.dom.$, on = QF.dom.on;
let context, question, answer = {}, acceptedAnswer = {}, writes = 0;
let initialized = false, actionBusy = false, confirming = false, controls = [];
await QF.page.register({
  onLoad(next) {
    context = next; question = next.question.data;
    if (!writes) answer = acceptedAnswer = next.attempt?.answer || {};
    if (initialized) refresh();
  },
  onBeforeLeave: () => ({ok: true, data: {pendingSave: null}})
});
QF.page.configure({initialLayout: {cardWidth: 720, maxCardWidth: '100%', horizontalAlign: 'center', verticalAlign: 'center', padding: 20}});
QF.ui.configure({typeLabel: false, position: false, score: false, state: false, submit: false, retry: false, confirmation: false, note: false, sources: false});
$('[data-type-label]').textContent = '判断题';
$('[data-choice-hint]').textContent = '请选择这句话的判断结果';
$('[data-prompt]').textContent = question.prompt.text;

async function runAction(action) {
  if (actionBusy) return;
  actionBusy = true; refresh();
  try {
    const reply = await action();
    if (!reply.ok) QF.ui.notify(reply.error.message);
    return reply;
  } finally { actionBusy = false; refresh(); }
}
on($('[data-submit-answer]'), 'click', () => { confirming = true; refresh(); $('[data-confirm-answer]').focus(); });
on($('[data-cancel-answer]'), 'click', () => { confirming = false; refresh(); });
on($('[data-confirm-answer]'), 'click', () => {
  confirming = false;
  return runAction(() => QF.save({purpose: 'submit', data: {answer}}));
});
on($('[data-retry-answer]'), 'click', () => runAction(() => QF.requestAction({action: 'retry'})));
on($('[data-sources]'), 'click', event => {
  const button = event.target.closest('[data-source-index]');
  if (button && !button.disabled) return runAction(() => QF.requestAction({action: 'openSource', params: {index: Number(button.dataset.sourceIndex)}}));
});

controls = [$('[data-answer-true]'), $('[data-answer-false]')].map((input, index) => {
  const option = question.payload.options[index], row = input.closest('label');
  input.value = option.id; input.setAttribute('aria-label', option.content.text);
  on(input, 'change', async () => {
    const candidate = {selectedOptionIds: [option.id]};
    answer = candidate; writes++;
    row.classList.toggle('selected', input.checked);
    try {
      const reply = await QF.save({purpose: 'draft', data: {answer: candidate}});
      if (reply.ok) acceptedAnswer = candidate;
      else QF.ui.notify(reply.error.message);
    } finally {
      writes--;
      if (!writes) { answer = acceptedAnswer; refresh(); }
    }
  });
  return {option, input, row, feedback: row.querySelector('.qf-option-feedback')};
});

function refresh() {
  const permissions = context.permissions, granted = context.grantedPermissions;
  const result = context.attempt?.result, selected = new Set(answer.selectedOptionIds || []);
  const readOnly = context.mode === 'history' || context.mode === 'preview';
  const navigation = context.navigation;
  $('[data-question-position]').textContent = '第 ' + (navigation.index + 1) + ' / ' + navigation.total + ' 题';
  $('[data-max-score]').textContent = '分值：' + (context.question.maxScore ?? '未设置');
  $('[data-answer-state]').textContent = ({unanswered: '未作答', draft: '已选择', submitted: '已提交', retrying: '重试中', revising: '修订中'})[context.attempt?.status] || '';
  if (!permissions.submit || result || readOnly) confirming = false;
  $('[data-answer-confirm]').hidden = !confirming;
  // 暂时失去交互能力时只禁用按钮，不改变题卡布局。
  $('[data-submit-answer]').hidden = readOnly || !granted.includes('practice.submit') || Boolean(result);
  $('[data-submit-answer]').disabled = actionBusy || confirming || !permissions.submit || !selected.size;
  $('[data-confirm-answer]').disabled = actionBusy || !permissions.submit || !selected.size;
  $('[data-retry-answer]').hidden = readOnly || !granted.includes('practice.retry') || !result;
  $('[data-retry-answer]').disabled = actionBusy || !permissions.retry;
  const rows = $('[data-sources]'); rows.replaceChildren();
  $('[data-source-section]').hidden = !context.sources.length;
  context.sources.forEach((source, index) => {
    const row = document.createElement('div'); row.className = 'qf-type-source';
    const button = document.createElement('button'); button.type = 'button'; button.textContent = source.label;
    button.disabled = actionBusy || !permissions.viewSources || !source.navigable; button.dataset.sourceIndex = index;
    const message = document.createElement('span'); message.className = 'muted'; message.textContent = source.message;
    row.append(button, message); rows.append(row);
  });
  $('[data-stage-note]').textContent = context.mode === 'history' ? '历史草稿 · 只读' : context.mode === 'preview' ? '只读预览' : '草稿自动保存；提交后冻结，重试从空白草稿开始。';
  const correct = result?.reference?.answerSpec?.correctOptionIds || result?.correctOptionIds || [];
  for (const {option, input, row, feedback} of controls) {
    if (!writes) input.checked = selected.has(option.id);
    input.disabled = actionBusy || confirming || readOnly || !permissions.writeAnswer;
    row.classList.toggle('selected', input.checked);
    row.classList.toggle('correct', Boolean(result) && correct.includes(option.id));
    row.classList.toggle('incorrect', Boolean(result) && input.checked && !correct.includes(option.id));
    feedback.hidden = !result || (!input.checked && !correct.includes(option.id));
    feedback.textContent = correct.includes(option.id) ? (input.checked ? '正确 · 已选' : '正确答案') : '你的答案';
  }
  $('[data-result]').hidden = !result;
  if (result) {
    $('[data-verdict]').textContent = ({CORRECT: '回答正确', INCORRECT: '回答错误', UNSCORED: '未评分'})[result.status] || '未评分';
    $('[data-verdict]').className = result.status === 'CORRECT' ? 'correct' : result.status === 'INCORRECT' ? 'incorrect' : 'muted';
    $('[data-score]').textContent = '得分：' + (result.score ?? '未评分') + ' / ' + result.maxScore;
    $('[data-correct-answer]').textContent = '正确答案：' + question.payload.options.filter(o => correct.includes(o.id)).map(o => o.content.text).join('、');
    QF.content.render($('[data-analysis]'), result.reference?.analysis || result.analysis || {kind: 'TEXT', text: ''});
  }
}
initialized = true; refresh();

assets.rulesSource:
// 独立、无 DOM 的规则文件。此处只有规则版 QF，不可使用页面的 editor/answer/dom 接口。
// 宿主载入 default.json，提供模板创建、复制、快照与默认单题大纲；作者只写业务规则。
QF.defineQuestionType({
  // 与 manifest.types[].id、default.json.type、题目 Schema 中 type.const 保持一致。
  type: 'TRUE_FALSE',
  // Schema 先校验结构，这里补业务约束；不能通过返回 [] 取消宿主 Schema 检查。
  validate(question) {
    const errors = [];
    if (question.prompt?.kind !== 'TEXT' || typeof question.prompt.text !== 'string' || !question.prompt.text.trim()) {
      errors.push('请填写普通文本题干');
    }
    const options = question.payload?.options;
    // 固定两项及顺序，同时保证 ID 独立；页面只改变哪个选项是标准答案。
    const validOptions = question.payload?.kind === 'CHOICE' && Array.isArray(options) && options.length === 2
      && options.every((option, index) => typeof option?.id === 'string' && option.id.startsWith('opt_')
        && option.content?.kind === 'TEXT' && option.content.text === ['正确', '错误'][index])
      && options[0].id !== options[1].id;
    if (!validOptions) errors.push('判断题需按顺序保留正确、错误两个固定选项和独立选项标识');
    const correct = question.answerSpec?.correctOptionIds;
    // 标准答案必须引用当前题目的有效选项，不能引用其他题目或默认模板的旧身份。
    if (question.answerSpec?.kind !== 'CHOICE' || !Array.isArray(correct) || correct.length !== 1
      || !validOptions || !options.some(option => option.id === correct[0])) errors.push('请选择有效的正确答案');
    if (!Number.isFinite(question.scoreSpec?.defaultMaxScore) || question.scoreSpec.defaultMaxScore <= 0) {
      errors.push('分值必须为正数');
    }
    return errors;
  },
  // 用户作答和标准答案分开校验；空数组可暂存，但 empty:true 会阻止直接提交。
  // 宿主保留的 {} 未作答状态由适配层处理，不会直接进入本函数。
  validateAnswer(question, answer) {
    const selected = answer.selectedOptionIds;
    const valid = Array.isArray(selected) && selected.length <= 1
      && selected.every(id => question.payload.options.some(option => option.id === id));
    return { empty: valid && selected.length === 0, errors: valid ? [] : ['请选择正确或错误中的一个选项'] };
  },
  // 同步评分使用应用提供的冻结题目、作答和满分，不能从页面读取 radio 或调用网络/AI。
  grade({ question, answer, maxScore, reportResult }) {
    const selected = answer.selectedOptionIds || [];
    const right = selected.length === 1 && selected[0] === question.answerSpec.correctOptionIds[0];
    // 每次上报一次，宿主验证 0～满分并在事务成功后保存；不是页面直接写入历史。
    // 规则适配层根据满分/非满分生成 CORRECT/INCORRECT，异步 Promise 评分尚未支持。
    return reportResult({ score: right ? maxScore : 0 });
  }
});

assets.stylesSource:
/* 判断题视觉模板：复制到新拓展后可定制。变量控制强调色、浅底、分隔与辅助文字。
   CSS 负责题型页面内部；题卡几何通过 QF.layout 配置，白板与浏览区导航由宿主提供。 */
.qf-judgment-editor, .qf-judgment-practice { --qf-accent: #7962ad; --qf-soft: #f5f1fb; --qf-line: #e8e3ed; --qf-muted: #8a8295; font: 15px/1.65 Arial, "Microsoft YaHei", sans-serif; color: #302c3b; min-width: 0; }
.qf-judgment-editor *, .qf-judgment-practice * { box-sizing: border-box }
/* JS 根据宿主能力切换 hidden；确保本文件其他 display 规则不会把隐藏控件重新显示。 */
.qf-extension-page [hidden] { display: none !important }
.qf-judgment-editor .muted, .qf-judgment-practice .muted { font-size: 12px; color: var(--qf-muted); margin: 0 }
.qf-type-heading { display: flex; align-items: center; justify-content: space-between; gap: 14px }
.qf-heading-copy { display: grid; gap: 3px; flex: 1 }
.qf-eyebrow { font-size: 11px; color: var(--qf-muted); letter-spacing: 1px }
.qf-editor-heading strong { font-size: 22px; font-weight: 600; line-height: 1.45 }
.qf-type-tag { padding: 4px 11px; border-radius: 6px; color: var(--qf-accent); background: #eee9f7; font-size: 12px }
.qf-type-meta { display: flex; justify-content: space-between; gap: 12px; font-size: 12px; color: var(--qf-muted); margin: 12px 0 24px }
.qf-type-actions { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin: 24px 0 0 }
.qf-editor-actions { margin: 18px 0 6px; padding-bottom: 20px; border-bottom: 1px solid var(--qf-line) }
.qf-judgment-editor button, .qf-judgment-practice button, .qf-judgment-editor select { font: 13px/1.5 Arial, "Microsoft YaHei", sans-serif; min-height: 36px; padding: 7px 13px; border: 1px solid #ded7e9; border-radius: 8px; background: white; color: var(--qf-accent); cursor: pointer; transition: background .15s, border-color .15s; }
.qf-judgment-editor button:hover, .qf-judgment-practice button:hover { background: var(--qf-soft); border-color: #c9bcde }
.qf-judgment-editor button.primary, .qf-judgment-practice button.primary { background: var(--qf-accent); color: white; border-color: var(--qf-accent); padding-left: 20px; padding-right: 20px }
.qf-judgment-editor button.primary:hover, .qf-judgment-practice button.primary:hover { background: #6a539d }
.qf-judgment-editor button:disabled, .qf-judgment-practice button:disabled { opacity: .45; cursor: default }
.qf-judgment-editor button.danger, .qf-judgment-editor button.quiet-danger { color: #bd5264 }
.qf-judgment-editor button:focus-visible, .qf-judgment-practice button:focus-visible, .qf-judgment-editor select:focus-visible { outline: 2px solid #ad97d5; outline-offset: 3px }
.qf-editor-section { margin-top: 24px }
.qf-field { display: grid; gap: 10px }
.qf-field-title, .qf-section-heading strong, .qf-type-sources>strong { font-size: 14px; font-weight: 600 }
.qf-section-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px }
.qf-judgment-editor textarea, .qf-judgment-editor input[type=number], .qf-source-input input { width: 100%; font: inherit; line-height: 1.65; padding: 11px 13px; border: 1px solid #dfd9e8; border-radius: 8px; background: #fff; color: inherit; outline: none; }
.qf-judgment-editor textarea { resize: vertical; display: block }
.qf-judgment-editor textarea:focus, .qf-judgment-editor input[type=number]:focus, .qf-source-input input:focus { border-color: #a18ac6; box-shadow: 0 0 0 3px #7962ad0d }
.qf-score-input { display: flex; align-items: center; gap: 10px; color: var(--qf-muted); font-size: 13px }
.qf-score-input input[type=number] { width: 112px; color: #302c3b }
.qf-analysis-editor { margin-top: 12px }
/* 普通文本保留换行，长词可换行；不要把题干改成依赖 innerHTML 的富文本实现。 */
.qf-choice-prompt { margin: 0 0 14px; white-space: pre-wrap; overflow-wrap: anywhere; font-size: 18px; font-weight: 500; line-height: 1.8 }
.qf-choice-hint { margin-bottom: 14px !important }
.qf-choice-option { display: flex; align-items: flex-start; gap: 12px; padding: 14px 15px; border: 1px solid #eeeaf2; border-radius: 10px; background: #fcfbfd; cursor: pointer; transition: background .15s, border-color .15s }
.qf-choice-option:hover { background: #f8f5fc; border-color: #d8cde7 }
.qf-choice-option.selected { background: var(--qf-soft); border-color: #d4c5e7 }
.qf-choice-option .qf-option-text { flex: 1; min-width: 0; white-space: pre-wrap; overflow-wrap: anywhere }
/* 保留原生 input 的 checked/disabled/键盘行为，仅定制外观。 */
.qf-choice-option input { appearance: none; -webkit-appearance: none; width: 20px; height: 20px; flex: none; position: relative; border: 1.5px solid #cec7d6; border-radius: 50%; margin: 2px 0 0; background: white; cursor: pointer; }
.qf-choice-option input[type=checkbox] { border-radius: 5px }
.qf-choice-option input:checked { border-color: var(--qf-accent) }
.qf-choice-option input:checked:after { content: ""; position: absolute; inset: 4px; background: var(--qf-accent); border-radius: 50% }
.qf-choice-option input[type=checkbox]:checked:after { content: "✓"; inset: -4px 0 0; color: var(--qf-accent); background: transparent; font-size: 19px; text-align: center }
.qf-choice-option input:focus-visible { outline: 2px solid #ad97d5; outline-offset: 3px }
/* 提交和历史只读后仍保留紫色已选圆点，禁用不代表清除答案。 */
.qf-choice-option input:disabled { opacity: 1; cursor: default }
/* 正确/错误来自接口返回的评分结果；文字反馈同时表达含义，避免只依赖颜色。 */
.qf-choice-option.correct { background: #edf7f3; border-color: #cce8dd; color: #13876d }
.qf-choice-option.incorrect { background: #fff0f2; border-color: #f2d3db; color: #c64b63 }
.qf-option-feedback { font-size: 11px; line-height: 24px; flex: none; white-space: nowrap }
.qf-inline-confirm { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 14px 16px; margin-top: 16px; background: var(--qf-soft); border: 1px solid #e0d6ed; border-radius: 10px; font-size: 13px }
.qf-inline-confirm>span { flex: 1; min-width: 180px }
.qf-result-panel { margin-top: 26px; padding: 20px; border: 1px solid var(--qf-line); border-radius: 12px; background: #fcfbfd }
.qf-result-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap }
.qf-result-heading p { margin: 0 }
.qf-result-heading [data-verdict] { font-size: 15px; font-weight: 600 }
.qf-result-heading .correct { color: #13876d }
.qf-result-heading .incorrect { color: #c64b63 }
.qf-result-score { font-size: 13px; color: var(--qf-accent); padding: 4px 10px; background: #eee9f7; border-radius: 6px }
.qf-correct-answer { margin: 12px 0 0; font-size: 13px; color: #6a6178 }
.qf-result-analysis { border-top: 1px solid var(--qf-line); padding-top: 16px; margin-top: 16px }
.qf-result-analysis>strong { font-size: 13px; font-weight: 600 }
.qf-result-analysis [data-analysis] { margin-top: 8px; overflow-wrap: anywhere }
.qf-type-sources { border-top: 1px solid var(--qf-line); padding-top: 18px; margin-top: 26px; font-size: 13px }
.qf-type-source { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; margin-top: 10px }
.qf-type-source>button:first-child { max-width: 100%; overflow-wrap: anywhere; text-align: left }
.qf-type-source>.muted { flex: 1 }
.qf-source-input { display: flex; align-items: center; gap: 10px; margin-top: 12px }
.qf-source-input input { flex: 1; min-width: 0; font-size: 13px }
.qf-source-input button { flex: none }
.qf-judgment-practice [data-stage-note] { margin-top: 24px; font-size: 11px; line-height: 1.7 }
@media(max-width:520px) {
.qf-editor-heading { flex-wrap: wrap }
.qf-heading-copy { min-width: 130px }
.qf-editor-heading strong { font-size: 20px }
.qf-choice-option { padding: 12px 10px; gap: 8px }
.qf-option-feedback { font-size: 10px }
.qf-result-panel { padding: 16px }
.qf-choice-prompt { font-size: 17px }
}
/* 判断题的固定两项同宽并排；后续题型可以替换自己的作答区域。 */
.qf-judgment-options { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 16px; }
.qf-judgment-options .qf-choice-option { align-items: center; flex-wrap: wrap; min-height: 76px; padding: 18px; }
.qf-judgment-options .qf-option-text { font-size: 16px; font-weight: 600; }
.qf-judgment-options input { margin: 0; }
.qf-judgment-symbol { font-size: 21px; font-weight: 500; line-height: 1; color: #8a8295; }
.qf-choice-option.selected .qf-judgment-symbol { color: var(--qf-accent); }
.qf-choice-option.correct .qf-judgment-symbol { color: #13876d; }
.qf-choice-option.incorrect .qf-judgment-symbol { color: #c64b63; }
.qf-choice-option:has(input:disabled) { cursor: default; }
.qf-choice-option:has(input:disabled):not(.selected):not(.correct):not(.incorrect):hover { background: #fcfbfd; border-color: #eeeaf2; }
.qf-judgment-options .qf-option-feedback { flex-basis: 100%; padding-left: 32px; }
/* 极窄区域改成单列，不设置固定高度或页面内部滚动容器。 */
@media (max-width: 380px) {
.qf-judgment-options { grid-template-columns: 1fr; }
}
/* 尊重用户的减少动态效果偏好。 */
@media (prefers-reduced-motion: reduce) {
.qf-choice-option, .qf-judgment-editor button, .qf-judgment-practice button { transition: none; }
}

/* Sample-owned card. Extensions may replace this layout entirely. */
.qf-choice-practice, .qf-judgment-practice { padding: 28px; background: #fff; border-radius: 14px; box-shadow: 0 2px 8px #302c3b0a; }
@media(max-width:480px) { .qf-choice-practice, .qf-judgment-practice { padding:18px; } }
